import csv,json,factstore
def st(a): return {r[0] for r in factstore.query(f'select v from "{a}"').rows}
rows=list(csv.DictReader(open('amazon/all_orders.txt'),delimiter='\t'))
S={'amazon/order_id':{r['amazon-order-id'] for r in rows},
'amazon/order_line':{r['amazon-order-id']+'/'+r['sku'] for r in rows}}
ob=list(csv.DictReader(open('3pl/outbound.csv')))
S['tpl/outbound_line']={r['Order Reference']+'/'+r['Item Code'] for r in ob}
rc=list(csv.DictReader(open('3pl/receipts.csv')))
S['tpl/receipt_no']={r['Receipt #'] for r in rc}
S['tpl/receipt_line']={r['Receipt #']+'/'+r['Item Code'] for r in rc}
S['amazon/fba_shipment_id']={r['Shipment ID'] for r in csv.DictReader(open('amazon/fba_inbound_shipments.csv'))}
o=[json.loads(l) for l in open('shopify/orders.jsonl')]
S['shopify/order_id']={r['id'].split('/')[-1] for r in o if 'Order/' in r['id']}
S['shopify/line_item_id']={r['id'].split('/')[-1] for r in o if 'LineItem' in r['id']}
S['shopify/customer_id']={r['customer']['id'].split('/')[-1] for r in o if 'Order/' in r['id']}
for a,s in S.items():
    t=st(a); print(a,len(s),len(t),'missing',len(s-t),'extra',len(t-s), list(t-s)[:3])
